          <option value="in:snoozed">Snoozed</option>
          <option value="in:spam">Spam</option>
          <option value="in:trash">Trash</option>
          <option value="in:anywhere">Mail &amp; Spam &amp; Trash</option>
          {state.labels.map((l) => (
            <option key={l.id} value={`label:${l.id}`}>
              {l.name}
            </option>
