+              >
+                <Avatar contact={c} size={32} />
+                <span className="suggest-text">
+                  <span className="strong">{c.name}</span>
+                  <span className="muted small">{c.email}</span>
+                </span>
+              </button>
+            ))}
+          </div>,
+          document.body,
+        )}
+    </div>
+  );
+}

