  }
  .empty {
    padding: 48px 24px;
  }
}

.m-title {
  display: none;
}
@media (max-width: 760px) {
  .m-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 8px 4px 16px;
    font-size: 12px;
    font-weight: 500;
    color: var(--text-3);
    text-transform: uppercase;
    letter-spacing: 0.4px;
  }
}

@media print {
  .header,
  .sidebar,
  .toolbar,
  .reply-area,
  .composer-dock,
  .toast,
  .fab,
  .thread-head-actions,
  .msg-actions .icon-btn,
  .split > .list-pane {
    display: none !important;
  }
  .app,
  .body,
  .main,
  .thread-pane,
  .thread-scroll {
    height: auto !important;
    overflow: visible !important;
    display: block !important;
    margin: 0 !important;
    border-radius: 0 !important;
    background: #fff !important;
  }
  .thread-head {
    padding-left: 16px;
  }
}

